// Some portions generated by Claude

// .agent/execplans/workbench-table-wrap-nquads.md: every table of statements can show its rows as N-Quads, and
// every page table can wrap its values or keep them on one line.
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');
const { FakeDocument } = require('./browser-fakes.js');
const { installDetailDisclosureTemplateRuntime } = require('./workbench-detail-disclosure-runtime.js');
const { renderPageResultTables, settle } = require('./page-result-table-harness.js');

const scripts = process.env.WORKBENCH_SCRIPT_DIR
    || path.resolve(__dirname, '../../tools/workbench/src/main/webapp/scripts');

function loadWorkbench() {
    const window = {};
    const workbench = {};
    installDetailDisclosureTemplateRuntime(workbench);
    const context = vm.createContext({ console, URL, URLSearchParams, Promise, window, workbench, setTimeout });
    for (const filename of ['workbenchViews.js', 'workbenchRoutes.js', 'queryStream.js', 'workbenchApp.js']) {
        vm.runInContext(fs.readFileSync(path.join(scripts, filename), 'utf8'), context, { filename });
    }
    window.workbench = context.workbench;
    return context.workbench;
}

const XSD = 'http://www.w3.org/2001/XMLSchema#';
const RDF = 'http://www.w3.org/1999/02/22-rdf-syntax-ns#';
const iri = value => ({ kind: 'iri', value });
const literal = (value, extra = {}) => Object.assign({ kind: 'literal', value }, extra);
const pageContext = { basePath: '/rdf4j-workbench', repositoryId: 'a', workbench: {} };

/** A ResultTable over rows in a fake document whose elements are width pixels wide. */
function standaloneTable(workbench, rows, variables, options = {}, source = {}, width = 1200) {
    const document = new FakeDocument();
    const createElement = document.createElement.bind(document);
    document.createElement = tagName => {
        const element = createElement(tagName);
        element.clientWidth = width;
        return element;
    };
    const root = document.createElement('div');
    document.body.appendChild(root);
    const table = new workbench.queryStream.ResultTable(root, Object.assign({
        rowCount: () => rows.length,
        variables: () => variables,
        read: async (start, count) => rows.slice(start, start + count),
        namespaces: () => [{ prefix: 'ex', name: 'http://example.org/' }]
    }, source), options);
    return { document, root, table };
}

function nquadLines(table) {
    return table.records.children.filter(child => child.classList.contains('query-result-nquad'))
        .map(line => line.textContent);
}

/**
 * The template values bound right after markup that matches pattern (an event handler such as @change=), with the
 * template's text and string values (id=${...}) read as one markup string.
 */
function findHandlers(template, pattern, found = []) {
    if (Array.isArray(template)) {
        template.forEach(value => findHandlers(value, pattern, found));
    } else if (template && Array.isArray(template.strings)) {
        let markup = '';
        template.strings.forEach((part, index) => {
            markup += part;
            if (index < template.values.length) {
                const value = template.values[index];
                if (pattern.test(markup.replace(/\s+/g, ' '))) {
                    found.push(value);
                }
                markup += typeof value === 'string' || typeof value === 'number' ? `"${value}"` : '';
            }
        });
        template.values.forEach(value => findHandlers(value, pattern, found));
    }
    return found;
}

test('N-Quads lines: full IRIs, escaped strings, tags, blank nodes, triple terms and the graph', () => {
    const { nquadsStatement, nquadsTerm } = loadWorkbench().queryStream;
    const s = iri('http://example.org/s');
    const p = iri('http://example.org/p');
    assert.equal(nquadsStatement([s, p, literal('plain', { datatype: XSD + 'string' }), null]),
        '<http://example.org/s> <http://example.org/p> "plain" .', 'the default graph has no fourth term');
    assert.equal(nquadsStatement([s, p, literal('42', { datatype: XSD + 'integer' }), iri('http://example.org/g')]),
        '<http://example.org/s> <http://example.org/p> "42"^^<http://www.w3.org/2001/XMLSchema#integer> '
        + '<http://example.org/g> .');
    assert.equal(nquadsTerm(literal('say "hi"\\\n\r\t\b\f\u0001\u007f end')),
        '"say \\"hi\\"\\\\\\n\\r\\t\\b\\f\\u0001\\u007F end"');
    assert.equal(nquadsTerm(literal('hallo', { language: 'de', datatype: RDF + 'langString' })), '"hallo"@de');
    assert.equal(nquadsTerm(literal('مرحبا', { language: 'ar', direction: 'rtl' })), '"مرحبا"@ar--rtl');
    assert.equal(nquadsTerm(iri('http://example.org/a b<c>"{|}^`\\')),
        '<http://example.org/a\\u0020b\\u003Cc\\u003E\\u0022\\u007B\\u007C\\u007D\\u005E\\u0060\\u005C>');
    assert.equal(nquadsTerm({ kind: 'bnode', value: 'b1' }), '_:b1');
    assert.equal(nquadsTerm({ kind: 'bnode', value: '_:b2', scope: '3:1' }), '_:b2', 'the server label is kept');
    assert.equal(nquadsTerm({ kind: 'triple', subject: s, predicate: p, object: literal('o') }),
        '<<( <http://example.org/s> <http://example.org/p> "o" )>>');
    assert.equal(nquadsStatement([[0, 'http://example.org/s'], [0, 'http://example.org/p'], [2, 'x', null, 'en', null],
        [0, 'http://example.org/g']]), '<http://example.org/s> <http://example.org/p> "x"@en <http://example.org/g> .',
    'packed row-store terms are read as well');
    assert.equal(nquadsStatement([s, p, null, null]), '', 'a row without an object is no statement');
});

test('the N-Quads layout shows one line per statement in the records box', async () => {
    const workbench = loadWorkbench();
    const rows = [
        [iri('http://example.org/s'), iri('http://example.org/p'), literal('one'), null],
        [iri('http://example.org/s'), iri('http://example.org/q'), literal('2', { datatype: XSD + 'integer' }),
            iri('http://example.org/g')]
    ];
    const { root, table } = standaloneTable(workbench, rows, ['subject', 'predicate', 'object', 'context'],
        { layout: 'nquads' }, { statements: () => true });
    await table.render();
    assert.equal(root.getAttribute('data-layout'), 'nquads');
    assert.equal(root.getAttribute('data-effective-layout'), 'nquads');
    assert.equal(table.tableWrap.hidden, true, 'the table is hidden');
    assert.equal(table.records.hidden, false, 'the lines are in the records box');
    assert.deepEqual(nquadLines(table), [
        '<http://example.org/s> <http://example.org/p> "one" .',
        '<http://example.org/s> <http://example.org/q> "2"^^<http://www.w3.org/2001/XMLSchema#integer> <http://example.org/g> .'
    ]);

    table.setLayout('records');
    await table.render();
    assert.equal(root.getAttribute('data-effective-layout'), 'records');
    assert.deepEqual(nquadLines(table), [], 'records replace the lines');
    assert.equal(table.records.children.filter(child => child.tagName === 'ARTICLE').length, 2);
    table.setLayout('nquads');
    await table.render();
    assert.equal(nquadLines(table).length, 2, 'and the lines come back');
    table.dispose();
});

test('the N-Quads layout reads whole statements for a table that shows some of their columns', async () => {
    const workbench = loadWorkbench();
    const full = [iri('http://example.org/s'), iri('http://example.org/p'), literal('o'), iri('http://example.org/g')];
    const { table } = standaloneTable(workbench, [[full[1], full[2]]], ['predicate', 'object'],
        { layout: 'nquads' }, { statements: () => true, statement: () => full });
    await table.render();
    assert.deepEqual(nquadLines(table),
        ['<http://example.org/s> <http://example.org/p> "o" <http://example.org/g> .']);
    table.dispose();
});

test('rows that are not statements fall back from N-Quads to the automatic layout', async () => {
    const workbench = loadWorkbench();
    const { root, table } = standaloneTable(workbench, [[iri('http://example.org/a')]], ['value'],
        { layout: 'nquads' }, { statements: () => false });
    await table.render();
    assert.equal(root.getAttribute('data-effective-layout'), 'table');
    assert.deepEqual(nquadLines(table), []);
    assert.equal(table.tableBody.children.filter(row => row.tagName === 'TR').length, 1);
    table.dispose();
});

test('Explore Display chooses the N-Quads layout and wrapping for every table of the page', async () => {
    const workbench = loadWorkbench();
    const resource = iri('urn:s');
    const rows = [
        [resource, iri('urn:p1'), literal('one'), null],
        [resource, iri('urn:p2'), iri('urn:o'), null],
        [iri('urn:x'), iri('urn:p3'), resource, iri('urn:g')]
    ];
    const model = { viewId: 'explore', vars: ['subject', 'predicate', 'object', 'context'], rows, rowCount: rows.length,
        rowStart: 0, namespaceMap: {}, links: [], metadata: { 'explore-resource': '<urn:s>' } };
    const page = await renderPageResultTables(workbench, model, pageContext);
    const outgoing = page.host('explore-outgoing');
    const incoming = page.host('explore-incoming');
    assert.ok(outgoing && incoming, 'rows about the resource are grouped');
    const template = workbench.views.outletOf(page.mount).template;
    const layout = findHandlers(template, /id="explore-result-layout"[^>]*@change=$/);
    const wrap = findHandlers(template, /id="explore-wrap-values"[^>]*@change=$/);
    assert.equal(layout.length, 1, 'Explore Display has a Layout select');
    assert.equal(wrap.length, 1, 'Explore Display has a Wrap values checkbox');

    layout[0]({ currentTarget: { value: 'nquads' } });
    await settle();
    assert.equal(outgoing.getAttribute('data-effective-layout'), 'nquads');
    const lines = host => host.querySelectorAll('.query-result-nquad').map(line => line.textContent);
    assert.deepEqual(lines(outgoing), ['<urn:s> <urn:p1> "one" .', '<urn:s> <urn:p2> <urn:o> .'],
        'the Outgoing lines name the subject the table leaves out');
    assert.deepEqual(lines(incoming), ['<urn:x> <urn:p3> <urn:s> <urn:g> .']);

    wrap[0]({ currentTarget: { checked: false } });
    await settle();
    assert.equal(outgoing.getAttribute('data-wrap'), 'false');
    assert.equal(incoming.getAttribute('data-wrap'), 'false');

    // A table built later on the page (the next Explore page) starts with the chosen presentation.
    workbench.views.releasePage(model);
    const next = await renderPageResultTables(workbench, Object.assign({}, model, { rowStore: null }), pageContext);
    assert.equal(next.host('explore-outgoing').getAttribute('data-effective-layout'), 'nquads');
    assert.equal(next.host('explore-outgoing').getAttribute('data-wrap'), 'false');
    layout[0]({ currentTarget: { value: 'auto' } });
    wrap[0]({ currentTarget: { checked: true } });
});

test('the Export and Remove previews offer N-Quads and Wrap values', async () => {
    const workbench = loadWorkbench();
    const statement = [iri('http://example.org/s'), iri('http://example.org/p'), literal('o'), null];
    const exportModel = { viewId: 'export', vars: ['subject', 'predicate', 'object', 'context'], rows: [statement],
        rowCount: 1, rowStart: 0, namespaceMap: {}, links: [], metadata: {} };
    const exported = await renderPageResultTables(workbench, exportModel, pageContext);
    const exportTemplate = workbench.views.outletOf(exported.mount).template;
    const exportLayout = findHandlers(exportTemplate, /id="export-preview-layout"[^>]*@change=$/);
    assert.equal(exportLayout.length, 1, 'the Export preview has a Layout select');
    assert.equal(findHandlers(exportTemplate, /id="export-preview-wrap-values"[^>]*@change=$/).length, 1);
    exportLayout[0]({ currentTarget: { value: 'nquads' } });
    await settle();
    assert.deepEqual(exported.host('export-preview').querySelectorAll('.query-result-nquad').map(line => line.textContent),
        ['<http://example.org/s> <http://example.org/p> "o" .']);
    exportLayout[0]({ currentTarget: { value: 'auto' } });

    const removeModel = { viewId: 'remove', vars: ['context'], rows: [], rowCount: 0, rowStart: 0,
        namespaceMap: {}, links: [], metadata: {} };
    removeModel.removePreview = { state: 'shown', rows: [statement], truncated: false, timedOut: false, message: '',
        controller: null, generation: 1 };
    const removed = await renderPageResultTables(workbench, removeModel, pageContext);
    const removeTemplate = workbench.views.outletOf(removed.mount).template;
    assert.equal(findHandlers(removeTemplate, /id="remove-preview-layout"[^>]*@change=$/).length, 1,
        'the Remove preview has a Layout select');
    assert.equal(findHandlers(removeTemplate, /id="remove-preview-wrap-values"[^>]*@change=$/).length, 1);
});

/** The markup of a page as one string: the template strings with their values written in place. */
function flatMarkup(template) {
    if (Array.isArray(template)) { return template.map(flatMarkup).join(''); }
    if (template && Array.isArray(template.strings)) {
        return template.strings.map((part, index) => part
            + (index < template.values.length ? flatMarkup(template.values[index]) : '')).join('');
    }
    return template == null || typeof template === 'function' ? '' : String(template);
}

test('the Repositories list has no Display control and always wraps its values', () => {
    const workbench = loadWorkbench();
    const runtime = { nothing: '', html(strings, ...values) { return { strings: Array.from(strings), values }; }, render() {} };
    const context = Object.assign({}, pageContext, { repositoryId: 'NONE',
        workbench: { menu: [{ id: 'all', label: 'All', items: [{ id: 'repositories', label: 'Repositories', href: 'repositories' },
            { id: 'types', label: 'Types', href: 'types' }] }] } });
    const repositories = { viewId: 'repositories', vars: ['id', 'description', 'location', 'readable', 'writeable'],
        rows: [[literal('r1'), literal('One'), literal('http://x/r1'), literal('true'), literal('true')]], rowCount: 1,
        metadata: {} };
    const markup = flatMarkup(workbench.views.pageTemplate(repositories, context, runtime));
    assert.match(markup, /id="repositories-results"[^>]*data-table-wrap="?true"?/, 'the list wraps its values');
    assert.doesNotMatch(markup, /repositories-display-options/, 'no Display disclosure');
    assert.doesNotMatch(markup, /repositories-wrap-values/, 'no Wrap values checkbox');
    assert.doesNotMatch(markup, /Table display options/, 'no Display control at all');

    // The other lists keep theirs.
    const types = { viewId: 'types', vars: ['type'], rows: [[iri('urn:T')]], rowCount: 1, metadata: {} };
    const typesMarkup = flatMarkup(workbench.views.pageTemplate(types, context, runtime));
    assert.match(typesMarkup, /types-display-options-toggle/, 'the Types list still has Display');
    assert.match(typesMarkup, /types-wrap-values/);
});
